agent_detail.agent_sql:
SELECT (COUNT(DISTINCT ?hero) AS ?n) WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/eye_colour_id> ?colourId .
  ?colour a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour> ;
          <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/id> ?colourId ;
          <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/colour> ?colourName .
  FILTER(?colourName = "Blue")

  ?hp a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower> ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower/hero_id> ?heroId ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower/power_id> ?powerId .
  ?hero <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/id> ?heroId .

  ?power a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower> ;
         <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower/id> ?powerId ;
         <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower/power_name> ?powerName .
  FILTER(?powerName = "Agility")
}

SELECT ?name WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/superhero_name> ?name ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/eye_colour_id> ?eyeColourId ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hair_colour_id> ?hairColourId .
  ?eyeColour a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour> ;
             <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/id> ?eyeColourId ;
             <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/colour> ?eyeColourName .
  ?hairColour a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour> ;
              <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/id> ?hairColourId ;
              <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/colour> ?hairColourName .
  FILTER(LCASE(?eyeColourName) = "blue")
  FILTER(LCASE(?hairColourName) = "blond")
}

SELECT (COUNT(?hero) AS ?n) WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/eye_colour_id> ?eyeColourId ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/publisher_id> ?publisherId .
  ?colour a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour> ;
          <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/id> ?eyeColourId ;
          <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/colour> ?colourName .
  FILTER(LCASE(STR(?colourName)) = "gold")
  ?publisher a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher> ;
             <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/id> ?publisherId ;
             <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/publisher_name> ?publisherName .
  FILTER(LCASE(STR(?publisherName)) = "marvel comics")
}

SELECT ?superhero_name ?height_cm WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Superhero/superhero_name> ?superhero_name ;
        <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Superhero/height_cm> ?height_cm ;
        <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?pub .
  ?pub a <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Publisher> ;
       <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Publisher/publisher_name> "Marvel Comics" .
  FILTER (xsd:integer(?height_cm) > 0)
}
ORDER BY DESC(xsd:integer(?height_cm))

SELECT ?superhero_name WHERE {
  ?power a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower> ;
         <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower/power_name> ?pname .
  FILTER(LCASE(?pname) = "death touch")
  ?hp a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower> ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower/hasSuperpower> ?power ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower/hasSuperhero> ?hero .
  ?hero <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/superhero_name> ?superhero_name .
}

SELECT (COUNT(*) AS ?n) WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hasGender> ?g .
  ?g <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Gender/gender> ?gender .
  FILTER(?gender = "Female")
}

SELECT (ABS(xsd:integer(?dc) - xsd:integer(?marvel)) AS ?difference) WHERE {
  {
    SELECT (COUNT(?h) AS ?dc) WHERE {
      ?h a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
         <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?p .
      ?p <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/publisher_name> "DC Comics" .
    }
  }
  {
    SELECT (COUNT(?h2) AS ?marvel) WHERE {
      ?h2 a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
          <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?p2 .
      ?p2 <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/publisher_name> "Marvel Comics" .
    }
  }
}

SELECT ?race WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/superhero_name> "Copycat" ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/race_id> ?raceId .
  ?r a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Race> ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Race/id> ?raceId ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Race/race> ?race .
}

SELECT (COUNT(?hero) AS ?n) WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Superhero> .
  OPTIONAL { ?hero <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Superhero/full_name> ?fn . }
  FILTER(!BOUND(?fn) || ?fn = "-" || ?fn = "")
}

SELECT (AVG(?weight) AS ?avgWeight) WHERE {
  ?g a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Gender> ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Gender/gender> "Female" ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Gender/id> ?gid .
  ?s a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/gender_id> ?gid ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/weight_kg> ?weight .
}

SELECT ?name WHERE {
  ?h a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/height_cm> ?height ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/superhero_name> ?name .
  FILTER(xsd:integer(?height) >= 170 && xsd:integer(?height) <= 190)
  FILTER NOT EXISTS { ?h <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/eye_colour_id> ?e }
}

SELECT ?id WHERE {
  ?p a <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Publisher> ;
     <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Publisher/publisher_name> "Star Trek" ;
     <http://bird-bird_superhero-ontology-20260805-012013/ontology/vkg-bird_superhero/Publisher/id> ?id .
}

SELECT ?publisher_name WHERE {
  ?attr a <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/Attribute> ;
        <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/Attribute/attribute_name> "Speed" ;
        <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/Attribute/id> ?attrId .
  ?ha a <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/HeroAttribute> ;
      <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/HeroAttribute/attributeId> ?attrId ;
      <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/HeroAttribute/heroId> ?heroId ;
      <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/HeroAttribute/attributeValue> ?val .
  ?hero a <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/Superhero/id> ?heroId ;
        <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/Superhero/publisher_id> ?pubId .
  ?pub a <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/Publisher> ;
       <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/Publisher/id> ?pubId ;
       <http://bird-bird_superhero-ontology-20260806-110735/ontology/vkg-bird_superhero/Publisher/publisher_name> ?publisher_name .
}
ORDER BY xsd:decimal(?val)
LIMIT 1

SELECT ?name WHERE {
  {
    SELECT (AVG(?w) AS ?avgW) WHERE {
      ?h a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
         <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/weight_kg> ?w .
    }
  }
  ?s a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/weight_kg> ?sw ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/superhero_name> ?name ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hasGender> ?g .
  ?g <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Gender/gender> "Male" .
  BIND((?avgW * 0.79) AS ?threshold)
  FILTER(xsd:decimal(?sw) > ?threshold)
}

SELECT ?power_name WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/superhero_name> "3-D Man" .
  ?hp a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower> ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower/hasSuperhero> ?hero ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower/hasSuperpower> ?sp .
  ?sp <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower/power_name> ?power_name .
}

SELECT ?heroName ?colourName ?cnt
WHERE {
  ?pub a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher> ;
       <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/publisher_name> "Marvel Comics" .
  ?hero a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?pub ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/superhero_name> ?heroName ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/eye_colour_id> ?eyeId .
  ?colour a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour> ;
          <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/id> ?eyeId ;
          <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/colour> ?colourName .
  {
    SELECT ?colourName2 (COUNT(?hero2) AS ?cnt)
    WHERE {
      ?pub2 a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher> ;
            <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/publisher_name> "Marvel Comics" .
      ?hero2 a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
             <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?pub2 ;
             <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/eye_colour_id> ?eyeId2 .
      ?colour2 a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour> ;
               <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/id> ?eyeId2 ;
               <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/colour> ?colourName2 .
    }
    GROUP BY ?colourName2
  }
  FILTER(?colourName = ?colourName2)
}
ORDER BY DESC(?cnt) ?heroName

SELECT ?totalHeroes ?neutralHeroes ?neutralMarvelHeroes (ROUND((xsd:decimal(?neutralHeroes)/xsd:decimal(?totalHeroes))*100) AS ?percentage)
WHERE {
  {
    SELECT (COUNT(?h) AS ?totalHeroes)
           (SUM(IF(?alignment = "Neutral", 1, 0)) AS ?neutralHeroes)
           (SUM(IF(?alignment = "Neutral" && ?publisher = "Marvel Comics", 1, 0)) AS ?neutralMarvelHeroes)
    WHERE {
      ?h a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
         <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hasAlignment> ?a .
      ?a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Alignment/alignment> ?alignment .
      OPTIONAL {
        ?h <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?p .
        ?p <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/publisher_name> ?publisher .
      }
    }
  }
}

SELECT ?name WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/superhero_name> ?name ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?pub .
  ?pub a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher> ;
       <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/publisher_name> "Dark Horse Comics" .
}

SELECT ?superhero_name WHERE {
  ?p a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher> ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/publisher_name> "Marvel Comics" ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/id> ?pid .

  ?s a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/publisher_id> ?pid ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/id> ?sid ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/superhero_name> ?superhero_name .

  ?hp a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower> ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower/hero_id> ?sid ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower/power_id> ?pwid .

  ?pw a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower> ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower/id> ?pwid ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower/power_name> "Super Strength" .
}

SELECT ?superhero_name ?height_cm
WHERE {
  ?s a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/superhero_name> ?superhero_name ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/height_cm> ?height_cm ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/eye_colour_id> ?eyeColourId .
  ?c a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour> ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/id> ?eyeColourId ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Colour/colour> ?colour .
  FILTER(LCASE(?colour) = "amber")
}

SELECT DISTINCT ?power_name WHERE {
  ?hero a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
        <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/gender_id> ?genderId .
  ?gender a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Gender> ;
          <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Gender/id> ?genderId ;
          <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Gender/gender> ?genderLabel .
  FILTER(?genderLabel = "Male")
  ?hp a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower> ;
      <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower/hero_id> ?heroId .
  ?hero <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/id> ?heroId .
  ?hp <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/HeroPower/power_id> ?powerId .
  ?power a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower> ;
         <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower/id> ?powerId ;
         <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superpower/power_name> ?power_name .
}
LIMIT 5

SELECT (100.0 * SUM(IF(?pname = "Marvel Comics", 1, 0)) / COUNT(*) AS ?percentage)
WHERE {
  ?h a <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero> ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/height_cm> ?height ;
     <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Superhero/hasPublisher> ?pub .
  ?pub <http://bird-bird_superhero-ontology-20260804-135249/ontology/vkg-bird_superhero/Publisher/publisher_name> ?pname .
  FILTER(xsd:decimal(?height) >= 150 && xsd:decimal(?height) <= 180)
}

SELECT ?superhero_name ?publisher_name WHERE {
